<?php
require_once 'config.php';require_login();$pdo=db();$projects=allowed_projects('view_project');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'add';$pid=(int)($_POST['project_id']??0);$eid=(int)($_POST['employee_id']??0);$date=(string)($_POST['advance_date']??'');$amount=$_POST['amount']??0;
 if(!can('add_expense',$pid)||!valid_date($date)||!positive_money($amount)){http_response_code(403);exit('Invalid permission, date or amount');}
 $check=$pdo->prepare("SELECT id FROM projects WHERE id=? AND status!='closed'");$check->execute([$pid]);if(!$check->fetchColumn())exit('Project is closed or invalid');
 $check=$pdo->prepare('SELECT id FROM users WHERE id=? AND active=1');$check->execute([$eid]);if(!$check->fetchColumn())exit('Invalid employee');
 $assignment=$pdo->prepare('SELECT 1 FROM project_assignments WHERE project_id=? AND user_id=?');$assignment->execute([$pid,$eid]);if(!$assignment->fetchColumn()){http_response_code(403);exit('Employee is not assigned to this project.');}
if($action==='edit'){
  $id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM employee_advances WHERE id=?');$st->execute([$id]);$old=$st->fetch();
  if(!$old||!can('edit_expense',(int)$old['project_id'])||!can('edit_expense',$pid)){http_response_code(403);exit('Edit not permitted');}
  $st=$pdo->prepare('UPDATE employee_advances SET project_id=?,employee_id=?,advance_date=?,amount=?,note=? WHERE id=?');$st->execute([$pid,$eid,$date,$amount,trim($_POST['note']??''),$id]);
 }else{$st=$pdo->prepare('INSERT INTO employee_advances(project_id,employee_id,advance_date,amount,note,entered_by) VALUES(?,?,?,?,?,?)');$st->execute([$pid,$eid,$date,$amount,trim($_POST['note']??''),user()['id']]);}
 flash('Advance saved.');redirect('advances.php');
}
$employees=$pdo->query('SELECT id,name FROM users WHERE active=1 ORDER BY name')->fetchAll();
if(is_admin())$rows=$pdo->query('SELECT a.*,p.title project_title,u.name employee_name FROM employee_advances a JOIN projects p ON p.id=a.project_id JOIN users u ON u.id=a.employee_id ORDER BY a.advance_date DESC,a.id DESC LIMIT 500')->fetchAll();
else{$st=$pdo->prepare('SELECT a.*,p.title project_title,u.name employee_name FROM employee_advances a JOIN projects p ON p.id=a.project_id JOIN users u ON u.id=a.employee_id JOIN project_assignments pa ON pa.project_id=p.id WHERE pa.user_id=? AND pa.view_project=1 ORDER BY a.advance_date DESC,a.id DESC LIMIT 500');$st->execute([user()['id']]);$rows=$st->fetchAll();}
include 'layout_top.php';?>
<section class="page-title"><div><h1>কর্মীর দৈনিক অগ্রিম</h1><p>প্রকল্প ও কর্মী অনুযায়ী অগ্রিমের হিসাব</p></div></section>
<section class="panel"><h2>অগ্রিম যোগ / সংশোধন</h2><form method="post" class="form-grid" id="advanceForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" id="action" value="add"><input type="hidden" name="id" id="recordId"><div><label>প্রকল্প</label><select name="project_id" id="pid" required><?php foreach($projects as $p):if(!can('add_expense',(int)$p['id'])||$p['status']==='closed')continue;?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></select></div><div><label>কর্মী</label><select name="employee_id" id="eid" required><?php foreach($employees as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach;?></select></div><div><label>তারিখ</label><input type="date" id="adate" name="advance_date" value="<?=date('Y-m-d')?>" required></div><div><label>অগ্রিম (৳)</label><input type="number" id="amount" name="amount" step=".01" min=".01" required></div><div class="wide"><label>বিবরণ</label><input id="note" name="note" maxlength="500"></div><button class="btn primary">সংরক্ষণ</button><button type="reset" class="btn" onclick="document.getElementById('action').value='add';document.getElementById('recordId').value=''">নতুন এন্ট্রি</button></form></section>
<section class="panel"><h2>দৈনিক অগ্রিমের তালিকা</h2><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>প্রকল্প</th><th>কর্মী</th><th>অগ্রিম</th><th>বিবরণ</th><th>সংশোধন</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['advance_date'])?></td><td><?=e($r['project_title'])?></td><td><?=e($r['employee_name'])?></td><td>৳<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['note'])?></td><td><?php if(can('edit_expense',(int)$r['project_id'])):?><button type="button" class="btn" onclick='editAdvance(<?=e(json_encode(["id"=>$r['id'],"project_id"=>$r['project_id'],"employee_id"=>$r['employee_id'],"advance_date"=>$r['advance_date'],"amount"=>$r['amount'],"note"=>$r['note']],JSON_HEX_APOS|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_QUOT))?>)'>Edit</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<script>function editAdvance(r){document.getElementById('action').value='edit';document.getElementById('recordId').value=r.id;document.getElementById('pid').value=r.project_id;document.getElementById('eid').value=r.employee_id;document.getElementById('adate').value=r.advance_date;document.getElementById('amount').value=r.amount;document.getElementById('note').value=r.note||'';window.scrollTo({top:0,behavior:'smooth'});}</script>
<?php include 'layout_bottom.php';?>
